// Puts the shared site header (scripts/site-header.mjs + css/site-nav.css)
// on every hand-maintained or already-generated static page, in place:
//
//   historical/**/*.html   the results archive (keeps its own account menu
//                          and settings modal - the menu moves into the
//                          header's right-hand slot)
//   college/**/*.html      standalone college pages, including the older
//                          week/game pages build-college-pages.mjs no longer
//                          regenerates
//   teams/index.html       (also regenerated by build-static-pages.mjs)
//   terms/, privacy/       policy pages
//   404.html
//
// The app shell (index.html and everything cut from it) is skipped: React
// draws that header.
//
// Idempotent: a page that already has the header gets the region between the
// site-hdr markers regenerated, so re-run this after any change to
// site-header.mjs, and after scripts/backfill-historical-season.mjs, which
// still emits the archive's original header.
//
// Run: node scripts/sync-site-header.mjs [--check]
import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { siteHeaderHtml, SITE_NAV_LINK, SITE_HDR_START, SITE_HDR_END } from "./site-header.mjs";

const ROOT = path.resolve(new URL(".", import.meta.url).pathname, "..");
const CHECK = process.argv.includes("--check");

async function walk(dir, out = []) {
  let entries;
  try { entries = await readdir(dir, { withFileTypes: true }); } catch (e) { return out; }
  for (const e of entries) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) await walk(p, out);
    else if (e.name.endsWith(".html")) out.push(p);
  }
  return out;
}

/** The balanced <div ...>...</div> starting at `start`, or null. */
function balancedDiv(html, start) {
  const re = /<div\b|<\/div>/g;
  re.lastIndex = start;
  let depth = 0, m;
  while ((m = re.exec(html))) {
    depth += m[0] === "</div>" ? -1 : 1;
    if (depth === 0) return html.slice(start, m.index + 6);
  }
  return null;
}

function ensureLink(html) {
  // Left where it is when already present (the generators put it right after
  // their <style>), so this script and the generators never undo each other.
  const re = /<link rel="stylesheet" href="\/css\/site-nav\.css[^>]*>/;
  if (re.test(html)) return html.replace(re, SITE_NAV_LINK);
  const i = html.indexOf("</head>");
  return i < 0 ? html : html.slice(0, i) + SITE_NAV_LINK + "\n" + html.slice(i);
}

/** [start, end) of the current header region: the marker pair if the page
 *  was synced before, else the page's original <header class="top">. */
function headerRegion(html) {
  const a = html.indexOf(SITE_HDR_START);
  if (a >= 0) {
    const b = html.indexOf(SITE_HDR_END, a);
    if (b >= 0) return [a, b + SITE_HDR_END.length];
  }
  const h = html.indexOf('<header class="top">');
  if (h < 0) return null;
  const e = html.indexOf("</header>", h);
  return e < 0 ? null : [h, e + 9];
}

function syncArchive(html) {
  const region = headerRegion(html);
  if (!region) return null;
  const old = html.slice(region[0], region[1]);
  const am = old.indexOf('<div class="account-menu"');
  const account = am >= 0 ? balancedDiv(old, am) : null;
  // First run only: the settings modal sat inside the old header. It is a
  // fixed overlay, so it moves out to be the header's next sibling.
  const sm = old.indexOf('<div class="settings-modal-overlay"');
  const settings = sm >= 0 ? balancedDiv(old, sm) : null;
  const header = siteHeaderHtml({ acts: account || undefined, top: "20px", side: "16px" });
  return html.slice(0, region[0]) + header + (settings ? "\n  " + settings : "") + html.slice(region[1]);
}

function syncPolicy(html) {
  const region = headerRegion(html);
  if (!region) return null;
  const old = html.slice(region[0], region[1]);
  // The old brand link wrapped the page's sr-only <h1>; keep the heading.
  const h1 = /<h1 class="sr-only">[^<]*<\/h1>/.exec(old);
  return html.slice(0, region[0]) + siteHeaderHtml({ top: "20px", side: "16px" }) + (h1 ? "\n    " + h1[0] : "") + html.slice(region[1]);
}

/** Standalone college pages and /teams/: `.wrap` shell with a brand + nav
 *  header. The section links stay as a sub-navigation row, minus the Home /
 *  NFL Games entries the shared header now carries. */
function syncWrap(html) {
  const region = headerRegion(html);
  if (!region) return null;
  const old = html.slice(region[0], region[1]);
  let sub = "";
  const nav = /<nav class="nav" aria-label="Site">(.*?)<\/nav>/s.exec(old);
  if (nav) {
    const links = nav[1].replace(/<a href="\/">Home<\/a>/, "").replace(/<a href="\/games\/">NFL Games<\/a>/, "").replace(/<a href="\/teams\/" class="on">Teams<\/a>/, "");
    if (links.trim()) sub = `\n<nav class="nav subnav" aria-label="Section">${links}</nav>`;
  }
  let out = html.slice(0, region[0]) + siteHeaderHtml({ top: "14px", side: "16px" }) + sub + html.slice(region[1]);
  if (sub && !out.includes(".subnav{")) {
    out = out.replace("</style>", ".nav{margin-left:0}.subnav{margin:0 0 12px;padding-bottom:10px;border-bottom:1px solid var(--border)}</style>");
  }
  return out;
}

const NOT_FOUND_STYLE = `<style id="site-hdr-404">body{flex-direction:column;justify-content:flex-start;padding-top:0}.site-hdr{align-self:stretch}main{margin:auto}</style>`;
function sync404(html) {
  let out = html;
  const a = out.indexOf(SITE_HDR_START);
  if (a >= 0) {
    const b = out.indexOf(SITE_HDR_END, a);
    out = out.slice(0, a) + out.slice(b + SITE_HDR_END.length).replace(/^\n/, "");
  }
  const body = /<body[^>]*>\n?/.exec(out);
  if (!body) return null;
  const at = body.index + body[0].length;
  out = out.slice(0, at) + siteHeaderHtml({ top: "0px", side: "1rem" }) + "\n" + out.slice(at);
  return out.includes('<style id="site-hdr-404">') ? out : out.replace("</head>", NOT_FOUND_STYLE + "\n</head>");
}

async function main() {
  const jobs = [];
  for (const f of await walk(path.join(ROOT, "historical"))) jobs.push([f, syncArchive]);
  for (const f of await walk(path.join(ROOT, "college"))) jobs.push([f, syncWrap]);
  jobs.push([path.join(ROOT, "teams", "index.html"), syncWrap]);
  jobs.push([path.join(ROOT, "terms", "index.html"), syncPolicy]);
  jobs.push([path.join(ROOT, "privacy", "index.html"), syncPolicy]);
  jobs.push([path.join(ROOT, "404.html"), sync404]);

  let changed = 0, skipped = 0, same = 0;
  for (const [file, fn] of jobs) {
    let html;
    try { html = await readFile(file, "utf8"); } catch (e) { skipped++; continue; }
    // App-shell pages (college/index.html, bowls) mount React: not ours.
    if (html.includes('id="root"')) { skipped++; continue; }
    const next = fn(html);
    if (next == null) { skipped++; console.warn("no header found, skipped:", path.relative(ROOT, file)); continue; }
    const withLink = ensureLink(next);
    if (withLink === html) { same++; continue; }
    changed++;
    if (!CHECK) await writeFile(file, withLink, "utf8");
  }
  console.log(`sync-site-header: ${changed} ${CHECK ? "would change" : "updated"}, ${same} already current, ${skipped} skipped.`);
  if (CHECK && changed) process.exit(1);
}

main().catch((err) => { console.error("sync-site-header FAILED:", err); process.exit(1); });
